seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
N=len(seq)
comp=str.maketrans('ACGT','TGCA')
def rc(s): return s.translate(comp)[::-1]
def mism(a,b): return sum(1 for x,y in zip(a,b) if x!=y)

# proper IR search: find j where seq[j:j+L] ~= revcomp(seq[i:i+L])
from collections import defaultdict
idx=defaultdict(list)
for p in range(N-7):
    idx[seq[p:p+8]].append(p)
hits=[]
for L in (15,20,25,30,40,50):
    tol=max(2, int(L*0.2))
    for i in range(N-L+1):
        target=rc(seq[i:i+L])
        cands=set()
        for off in (0, (L-8)//2, L-8):
            for p in idx.get(target[off:off+8],[]):
                j=p-off
                if 0<=j and j+L<=N: cands.add(j)
        for j in cands:
            if j>i+5:
                m=mism(seq[j:j+L], target)
                if m<=tol:
                    hits.append((L,m,i,j))
hits.sort(key=lambda x:(-x[0],x[1]))
print(len(hits))
for h in hits[:30]:
