def scan(s, name):
    res=[]
    for f in range(3):
        i=f
        start=None
        aa=[]
        while i+3<=len(s):
            c=s[i:i+3]
            a=code[c]
            if start is None:
                if c in ('ATG','GTG','TTG'):
                    start=i; aa=[('ATG' if a=='M' else a)]
                    # treat as potential start
                    i+=3
                    continue
                else:
                    i+=3; continue
            if a=='*':
                if len(aa)>=30:
                    res.append((name,start,i+3,len(aa),''.join(aa)))
                start=None; aa=[]; i+=3
            else:
                aa.append(a); i+=3
        if start is not None and len(aa)>=30:
            res.append((name,start,len(s),len(aa),''.join(aa)))
    return res
